import{c as r,Q as t,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"From Prompts to Contracts: Harness Engineering for Auditable Enterprise LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.08028","title":"From Prompts to Contracts: Harness Engineering for Auditable Enterprise LLM Agents","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2607.08028,"authors":["Joongho Ahn","Moonsoo Kim"],"pdf_path":"pdfs/2607.08028.pdf","published_date":"2026-07-09T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-07-09-from-prompts-to-contracts-harness-engineering-2607-08028.md","filePath":"research/papers/2026-07-09-from-prompts-to-contracts-harness-engineering-2607-08028.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-07-09-from-prompts-to-contracts-harness-engineering-2607-08028.md"};function o(i,e,c,l,p,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="from-prompts-to-contracts-harness-engineering-for-auditable-enterprise-llm-agents" tabindex="-1">From Prompts to Contracts: Harness Engineering for Auditable Enterprise LLM Agents <a class="header-anchor" href="#from-prompts-to-contracts-harness-engineering-for-auditable-enterprise-llm-agents" aria-label="Permalink to &quot;From Prompts to Contracts: Harness Engineering for Auditable Enterprise LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Joongho Ahn, Moonsoo Kim <strong>Published</strong>: July 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2607.08028" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.08028</a><strong>arXiv ID</strong>: 2607.08028 <strong>Categories</strong>: Artificial Intelligence (cs.AI); Computation and Language (cs.CL); Software Engineering (cs.SE) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2607.08028" target="_blank" rel="noreferrer">research/papers/pdfs/2607.08028.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The paper presents an engineering framework that transforms exploratory LLM prototypes into production-ready systems. Rather than relying solely on prompt-based behavior, the authors propose moving deterministic behavior into code, manifests, schemas, and validation artifacts while maintaining source-backed claims as the foundation for runtime answers. The research evaluates three key aspects: first, the harness maintains its contractual guarantees across validation scenarios, with fault injection confirming validators detect broken contracts; second, enforcement checks remain effective across different model substitutions, with 270 composition-boundary runs passing; third, code-level enforcement is essential — prompt-only instructions alone permit policy violations that the harness prevents entirely. Compared to external guardrails (which achieve only 88/120 utility by over-refusing), the approach preserves full utility at 120/120 while maintaining safety and auditability. The pattern is instantiated on Korean corporate data spanning five groups and 25 listed companies.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>主張「合約優先」harness 設計：把可稽核行為從 prompt 移到程式碼/manifest/schema/驗證器，prompt 只負責探索性行為，硬性保證由確定性程式碼承擔。</li><li>Fault injection 實測驗證器能偵測合約破壞；模型替換（model substitution）下 270 次 composition-boundary 測試仍守住 enforcement，證明 harness-level 保證與底層模型解耦。</li><li>對比外部 guardrail（過度拒絕、僅 88/120 utility）與本框架（120/120 utility 同時維持安全與可稽核性），顯示「code-level enforcement &gt; prompt-only instruction」。</li><li><strong>Workspace 關聯</strong>：與 core.md 公理「LLM 只做判斷、確定性程式碼做決定」高度一致；「prompt-only 允許政策違反，harness 完全阻擋」佐證本 workspace 硬性執行交給 hooks 而非 advisory 規則的既有立場。</li></ul>',8)])])}const g=r(n,[["render",o]]);export{m as __pageData,g as default};
